<div class="panel"><h2>Pengaturan PPDB</h2>
<p>Status saat ini: <?php if ($cfg['is_open'] && $period): ?><span class="badge badge-ok">DIBUKA</span> — <?= e($period['name']) ?> (s.d. <?= e(fmt_date($period['end_date'])) ?>)<?php elseif ($cfg['is_open']): ?><span class="badge badge-off">DITUTUP OTOMATIS</span> — tidak ada gelombang yang sedang berjalan.<?php else: ?><span class="badge badge-off">DITUTUP</span><?php endif; ?></p>
<form class="form" method="post" action="<?= e(url('admin/ppdb-pengaturan')) ?>"><?= Csrf::field() ?>
<label class="check"><input type="checkbox" name="is_open" value="1" <?= $cfg['is_open'] ? 'checked' : '' ?>> Buka pendaftaran (tetap hanya aktif jika ada gelombang berjalan)</label>
<?php if (array_key_exists('auto_accept', $cfg)): ?><label class="check"><input type="checkbox" name="auto_accept" value="1" <?= !empty($cfg['auto_accept']) ? 'checked' : '' ?>> Otomatis tandai pendaftar baru sebagai <strong>DITERIMA</strong> (jika dimatikan, status awal "baru" dan Anda mengubahnya manual di detail pendaftar)</label><?php endif; ?>
<div class="row2"><div class="field"><label>Informasi</label><textarea name="info"><?= e($cfg['info']) ?></textarea></div><div class="field"><label>Pesan saat ditutup</label><textarea name="closed_message" style="min-height:60px"><?= e($cfg['closed_message']) ?></textarea></div></div>
<div class="row2"><div class="field"><label>Persyaratan (satu per baris)</label><textarea name="requirements"><?= e($cfg['requirements']) ?></textarea></div><div class="field"><label>Alur (satu per baris)</label><textarea name="flow"><?= e($cfg['flow']) ?></textarea></div></div>
<div class="field"><label>Biaya</label><textarea name="fees" style="min-height:60px"><?= e($cfg['fees']) ?></textarea></div>
<div class="row2"><?php foreach ($majors as $m): ?><div class="field"><label>Kuota <?= e($m['code']) ?></label><input type="number" name="quota[<?= (int)$m['id'] ?>]" min="0" max="9999" value="<?= (int)$m['ppdb_quota'] ?>"></div><?php endforeach; ?></div>
<div class="toolbar"><button class="btn btn-primary" type="submit">Simpan</button><a class="btn btn-outline" href="<?= e(url('admin/m/ppdb_periods')) ?>">Kelola gelombang</a></div></form></div>
<div class="panel"><h2>Pendaftar</h2>
<form method="get" class="toolbar"><input type="search" name="q" value="<?= e($q) ?>" placeholder="Nama / NISN / No."><select name="status"><option value="">Semua status</option><?php foreach ($statuses as $s): ?><option <?= $s === $st ? 'selected' : '' ?>><?= e($s) ?></option><?php endforeach; ?></select><select name="jurusan"><option value="">Semua jurusan</option><?php foreach ($majors as $m): ?><option value="<?= (int)$m['id'] ?>" <?= (int)$m['id'] === $mj ? 'selected' : '' ?>><?= e($m['code']) ?></option><?php endforeach; ?></select><button class="btn btn-outline" type="submit">Filter</button><span class="sp"></span><a class="btn btn-primary" href="<?= e(url('admin/ppdb-export?' . http_build_query(array_filter(['q' => $q, 'status' => $st, 'jurusan' => $mj])))) ?>"><?= icon('download', 14) ?> Ekspor CSV</a></form>
<div class="table-wrap"><table class="t"><thead><tr><th>No. Pendaftaran</th><th>Nama</th><th>NISN</th><th>Jurusan</th><th>Status</th><th>Tanggal</th><th></th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="7" class="muted">Belum ada pendaftar.</td></tr><?php endif; ?>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['reg_number']) ?></td><td><?= e($r['name']) ?></td><td><?= e($r['nisn']) ?></td><td><?= e($r['major_code']) ?></td><td><span class="badge"><?= e($r['status']) ?></span></td><td><?= e(fmt_date($r['created_at'], 'd M Y H:i')) ?></td><td><a class="btn btn-sm btn-outline" href="<?= e(url('admin/ppdb/' . $r['id'])) ?>">Detail</a></td></tr><?php endforeach; ?></tbody></table></div>
<?= pager($pg, ['q' => $q, 'status' => $st, 'jurusan' => $mj ?: '']) ?></div>
